import React, { useState, useEffect, useCallback } from 'react';
import { supabase } from '../../supabaseClient';
import { useAuth } from '../../context/AuthContext';

const ArtistPortfolio = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [portfolio, setPortfolio] = useState([]);
  const [message, setMessage] = useState('');
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    file: null,
    preview: null
  });

  useEffect(() => {
    if (user?.id) {
      loadPortfolio();
    } else {
      setLoading(false);
    }
  }, [user?.id, loadPortfolio]);

  const loadPortfolio = useCallback(async () => {
    if (!user?.id) {
      setLoading(false);
      return;
    }

    try {
      const { data, error } = await supabase
        .from('portfolio')
        .select('*')
        .eq('artist_id', user.id)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setPortfolio(data || []);
    } catch (error) {
      console.error('Error loading portfolio:', error);
      setMessage('Error loading portfolio');
    } finally {
      setLoading(false);
    }
  }, [user?.id]);

  const handleFileSelect = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Validate file type
    if (!file.type.startsWith('image/')) {
      setMessage('Please select a valid image');
      return;
    }

    // Validate file size (max 10MB)
    if (file.size > 10 * 1024 * 1024) {
      setMessage('Image must be at most 10MB');
      return;
    }

    const preview = URL.createObjectURL(file);
    setFormData(prev => ({ ...prev, file, preview }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.file && !editingItem) {
      setMessage('Please select an image');
      return;
    }

    setUploading(true);
    setMessage('');

    try {
      let imageUrl = editingItem?.image_url;

      // Upload new image if file was selected
      if (formData.file) {
        const fileExt = formData.file.name.split('.').pop();
        const fileName = `${user.id}/portfolio/${Date.now()}-${Math.random().toString(36).substring(7)}.${fileExt}`;

        const { error: uploadError } = await supabase.storage
          .from('portfolio-images')
          .upload(fileName, formData.file, {
            cacheControl: '3600',
            upsert: false
          });

        if (uploadError) throw uploadError;

        const { data: urlData } = supabase.storage
          .from('portfolio-images')
          .getPublicUrl(fileName);

        imageUrl = urlData.publicUrl;
      }

      const portfolioData = {
        artist_id: user.id,
        title: formData.title,
        description: formData.description,
        image_url: imageUrl
      };

      if (editingItem) {
        // Update existing item
        const { error } = await supabase
          .from('portfolio')
          .update(portfolioData)
          .eq('id', editingItem.id);

        if (error) throw error;
        setMessage('✅ Item updated successfully!');
      } else {
        // Insert new item
        const { error } = await supabase
          .from('portfolio')
          .insert(portfolioData);

        if (error) throw error;
        setMessage('✅ Image added to portfolio!');
      }

      // Reset form
      resetForm();
      await loadPortfolio();
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      console.error('Error saving portfolio item:', error);
      setMessage(`❌ Error: ${error.message}`);
    } finally {
      setUploading(false);
    }
  };

  const handleEdit = (item) => {
    setEditingItem(item);
    setFormData({
      title: item.title,
      description: item.description || '',
      file: null,
      preview: item.image_url
    });
    setShowAddForm(true);
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this image?')) return;

    try {
      const { error } = await supabase
        .from('portfolio')
        .delete()
        .eq('id', id);

      if (error) throw error;

      setMessage('✅ Image removed from portfolio');
      await loadPortfolio();
      setTimeout(() => setMessage(''), 3000);
    } catch (error) {
      console.error('Error deleting portfolio item:', error);
      setMessage(`❌ Error deleting: ${error.message}`);
    }
  };

  const resetForm = () => {
    setFormData({
      title: '',
      description: '',
      file: null,
      preview: null
    });
    setShowAddForm(false);
    setEditingItem(null);
    if (formData.preview && formData.file) {
      URL.revokeObjectURL(formData.preview);
    }
  };

  if (loading) {
    return <div className="loading">Loading portfolio...</div>;
  }

  return (
    <div className="artist-portfolio-manager">
      <div className="portfolio-header">
        <div>
          <h2 className="section-title">My Portfolio</h2>
          <p className="subtitle">
            Show your best work to architects
          </p>
        </div>
        {!showAddForm && (
          <button
            onClick={() => setShowAddForm(true)}
            className="btn-primary"
          >
            + Add Image
          </button>
        )}
      </div>

      {message && (
        <div className={`message ${message.includes('✅') ? 'message-success' : 'message-error'}`}>
          {message}
        </div>
      )}

      {showAddForm && (
        <div className="portfolio-form-card">
          <h3 className="form-card-title">
            {editingItem ? 'Edit Image' : 'Add New Image'}
          </h3>

          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label className="form-label">Image *</label>
              {formData.preview ? (
                <div className="image-upload-preview">
                  <img src={formData.preview} alt="Preview" />
                  <button
                    type="button"
                    onClick={() => {
                      if (formData.file) URL.revokeObjectURL(formData.preview);
                      setFormData(prev => ({ ...prev, file: null, preview: null }));
                    }}
                    className="preview-remove-btn"
                  >
                    Remove Image
                  </button>
                </div>
              ) : (
                <label className="file-upload-area">
                  <div className="file-upload-content">
                    <p className="file-upload-text">📸 Click to select an image</p>
                    <p className="file-upload-hint">JPG, PNG or GIF (max 10MB)</p>
                  </div>
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleFileSelect}
                    className="file-input-hidden"
                  />
                </label>
              )}
            </div>

            <div className="form-group">
              <label className="form-label">Project Title *</label>
              <input
                type="text"
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                placeholder="Ex: Modern House in São Paulo"
                required
                className="form-input"
              />
            </div>

            <div className="form-group">
              <label className="form-label">Description (Optional)</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Describe the project, techniques used, software..."
                rows="4"
                className="form-textarea"
              />
            </div>

            <div className="form-actions">
              <button
                type="button"
                onClick={resetForm}
                className="btn-secondary"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={uploading}
                className="btn-primary"
              >
                {uploading ? 'Saving...' : editingItem ? 'Update' : 'Add'}
              </button>
            </div>
          </form>
        </div>
      )}

      <div className="portfolio-grid">
        {portfolio.length === 0 ? (
          <div className="empty-state">
            <p className="empty-state-title">Your portfolio is empty</p>
            <p className="empty-state-text">
              Add your best work to impress architects!
            </p>
          </div>
        ) : (
          portfolio.map(item => (
            <div key={item.id} className="portfolio-item-card">
              <div className="portfolio-image-wrapper">
                <img
                  src={item.image_url}
                  alt={item.title}
                  className="portfolio-image"
                  loading="lazy"
                  decoding="async"
                />
              </div>
              <div className="portfolio-item-content">
                <h4 className="portfolio-item-title">{item.title}</h4>
                {item.description && (
                  <p className="portfolio-item-description">{item.description}</p>
                )}
                <div className="portfolio-item-actions">
                  <button
                    onClick={() => handleEdit(item)}
                    className="btn-edit"
                  >
                    Edit
                  </button>
                  <button
                    onClick={() => handleDelete(item.id)}
                    className="btn-delete"
                  >
                    Delete
                  </button>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default ArtistPortfolio;